import crypto from 'node:crypto'
import fs from 'node:fs/promises'
import path from 'node:path'

/**
 * The media cache: indexes kept on disk so a file is demuxed once, not once
 * per open.
 *
 * ## Why this is not in the project
 *
 * Because it is not the user's work. An index is derived from the media and
 * can be rebuilt from it at any time, so keeping it in the project folder
 * would put a megabyte of machine-generated bytes per clip next to the one
 * file that is supposed to *be* the project — in the folder they browse, in
 * the zip they send someone, in the git diff. Premiere does the same thing for
 * the same reason: its media cache lives with the user's app data, and the one
 * you are told to delete when something goes strange is not your project.
 *
 * Keeping it out of the project also gets sharing for free. Two projects
 * cutting the same footage index it once between them.
 *
 * ## What makes an entry stale
 *
 * The source's size and modification time, stored with the entry and checked
 * against the file every time. If either has moved, the entry is ignored — a
 * cache that hands back an index for bytes that have since changed does not
 * fail loudly, it feeds the decoder offsets into a file that is no longer
 * shaped that way.
 *
 * That check has a window in it, and the token closes it. A file being written
 * while it is indexed — a recording still running, a copy still going — would
 * otherwise be read at one length and stamped with the length it reached by
 * the time the entry was written, and the entry would then look current
 * forever. So the identity observed *before* the index is built travels back
 * with the request, and a write is refused unless the file still matches it.
 *
 * ## No electron import
 *
 * Same rule as electron/project.js: the cache directory is passed in, so all
 * of this can be exercised against a real temp directory from a plain Node
 * script with no app running. See scripts/verify-demux.mjs.
 */

/** 'FLXC'. */
const MAGIC = 0x464c5843

/** Entry layout. Independent of the index format inside it. */
const ENTRY_FORMAT = 1

/**
 * The envelope around an index.
 *
 *    0  u32  magic
 *    4  u16  entry format
 *    6  u16  identity token length
 *    8  u32  payload length
 *   12  u16  source path length
 *   14       reserved to 32
 *
 * then the token, the source path, and the index itself. What is *inside* the
 * payload is none of this file's business — see shared/mp4Index.js, which has
 * its own version and its own checksum. The split matters: this layer decides
 * whether an entry is for the right bytes, that one decides whether the bytes
 * are intact, and neither alone would catch both.
 */
const HEADER_BYTES = 32

/** File name suffix, so a stray file in the directory is never read as one. */
const SUFFIX = '.fluxidx'

/**
 * How much disk the cache may hold before the least recently used entries go.
 *
 * Generous, because an index is small next to what it stands for: 256MB of
 * indexes is roughly two hundred hours of footage, and the media itself would
 * be terabytes. The budget exists so the directory cannot grow without limit,
 * not because the space is precious.
 */
export const CACHE_BUDGET_BYTES = 256 * 1024 * 1024

/**
 * One entry per source path.
 *
 * Windows paths are case-insensitive, so the same file reached two ways must
 * not index twice. Keying by path rather than by content means a file that is
 * edited in place replaces its own entry instead of orphaning it — the reason
 * the directory does not fill up with supersedings.
 */
export function cacheKey(filePath) {
  const resolved = path.resolve(filePath)
  const normalised = process.platform === 'win32' ? resolved.toLowerCase() : resolved
  return crypto.createHash('sha256').update(normalised).digest('hex').slice(0, 32)
}

/** The file an index for `filePath` lives in. Exported so a harness can damage one. */
export function entryPath(dir, filePath) {
  return path.join(dir, `${cacheKey(filePath)}${SUFFIX}`)
}

/** The same normalisation cacheKey hashes, so a stored path can be compared to a live one. */
function comparablePath(filePath) {
  const resolved = path.resolve(filePath)
  return process.platform === 'win32' ? resolved.toLowerCase() : resolved
}

/** What identifies a version of a file: how big it is and when it last changed. */
export function identityToken(stat) {
  return `${stat.size}:${stat.mtimeMs}`
}

/**
 * The source's current identity, or null if it cannot be read.
 *
 * Handed to the renderer with a lookup and handed back with a write, so the
 * two can be compared across the time it takes to demux.
 */
export async function sourceToken(filePath) {
  try {
    const stat = await fs.stat(filePath)
    if (!stat.isFile()) return null
    return identityToken(stat)
  } catch {
    return null
  }
}

/**
 * The cached index for a file, or null if there is none that matches `token`.
 *
 * The token comes from the caller rather than being read here, so the identity
 * a lookup is answered against is the same one the eventual write is checked
 * against. Two stats a few milliseconds apart could disagree, and the failure
 * that produces — an entry stored under an identity nobody ever asked for — is
 * invisible until it is handed back for the wrong bytes.
 *
 * @returns {Promise<Uint8Array | null>}
 */
export async function readIndex(dir, filePath, token) {
  if (!token) return null

  let raw
  try {
    raw = await fs.readFile(entryPath(dir, filePath))
  } catch {
    return null
  }

  const bytes = parseEntry(raw, comparablePath(filePath), token)
  if (!bytes) return null

  // Last *used*, not last written, so the prune keeps what is actually being
  // cut with. Deliberately not awaited: a lookup must not wait on bookkeeping,
  // and an entry that fails to be touched is only a candidate to be dropped
  // sooner.
  const now = new Date()
  fs.utimes(entryPath(dir, filePath), now, now).catch(() => {})

  return bytes
}

/**
 * Pulls the payload out of an entry, or null unless it is for this file at
 * this version of it.
 *
 * Every failure here is ordinary: a half-written file from a crash, an entry
 * from an older layout, a source that has changed underneath it. All of them
 * mean "demux the file", which is what would have happened without a cache.
 *
 * The entry names the file it belongs to as well as the version, which the
 * key already implies. Two reasons to write it down anyway: a directory of
 * hex-named files is otherwise impossible to make sense of by looking at it,
 * and a key is a truncated hash — cheap to make self-evidently right rather
 * than probably right.
 */
function parseEntry(raw, filePath, token) {
  if (raw.length < HEADER_BYTES) return null
  const head = new DataView(raw.buffer, raw.byteOffset, raw.byteLength)

  if (head.getUint32(0, true) !== MAGIC) return null
  if (head.getUint16(4, true) !== ENTRY_FORMAT) return null

  const tokenLength = head.getUint16(6, true)
  const payloadLength = head.getUint32(8, true)
  const pathLength = head.getUint16(12, true)
  if (raw.length !== HEADER_BYTES + tokenLength + pathLength + payloadLength) return null

  const text = new TextDecoder()
  const at = raw.byteOffset + HEADER_BYTES
  const storedToken = text.decode(new Uint8Array(raw.buffer, at, tokenLength))
  if (storedToken !== token) return null
  const storedPath = text.decode(new Uint8Array(raw.buffer, at + tokenLength, pathLength))
  if (storedPath !== filePath) return null

  const from = at + tokenLength + pathLength
  return new Uint8Array(raw.buffer.slice(from, from + payloadLength))
}

/**
 * Stores an index against the file it was built from.
 *
 * Refused — quietly, and reported as `stale` — when the file no longer matches
 * the identity the index was built against. See the note about the window at
 * the top of this file.
 *
 * @returns {Promise<{ ok: true, bytes: number } | { ok: false, reason: string }>}
 */
export async function writeIndex(dir, filePath, token, payload) {
  if (!token || !payload || payload.length === 0) return { ok: false, reason: 'nothing-to-write' }

  const now = await sourceToken(filePath)
  if (now === null) return { ok: false, reason: 'source-missing' }
  if (now !== token) return { ok: false, reason: 'stale' }

  const encoder = new TextEncoder()
  const tokenBytes = encoder.encode(token)
  const pathBytes = encoder.encode(comparablePath(filePath))
  const out = new Uint8Array(
    HEADER_BYTES + tokenBytes.length + pathBytes.length + payload.length,
  )
  const head = new DataView(out.buffer)
  head.setUint32(0, MAGIC, true)
  head.setUint16(4, ENTRY_FORMAT, true)
  head.setUint16(6, tokenBytes.length, true)
  head.setUint32(8, payload.length, true)
  head.setUint16(12, pathBytes.length, true)
  out.set(tokenBytes, HEADER_BYTES)
  out.set(pathBytes, HEADER_BYTES + tokenBytes.length)
  out.set(payload, HEADER_BYTES + tokenBytes.length + pathBytes.length)

  const target = entryPath(dir, filePath)
  // Written aside and renamed. A cache entry torn in half by a crash would be
  // rejected on read rather than believed, but it would also sit there taking
  // up the budget and being rebuilt every time; renaming means an entry either
  // exists complete or does not exist.
  const temp = `${target}.tmp-${process.pid}`
  try {
    await fs.mkdir(dir, { recursive: true })
    await fs.writeFile(temp, out)
    await fs.rename(temp, target)
  } catch (err) {
    await fs.rm(temp, { force: true }).catch(() => {})
    return { ok: false, reason: err.code === 'ENOSPC' ? 'no-space' : 'write-failed' }
  }

  return { ok: true, bytes: out.length }
}

/**
 * Drops the least recently used entries until the cache fits its budget.
 *
 * Run once at startup and never on the path a lookup takes: deciding what to
 * drop means stating every entry in the directory, which is fine occasionally
 * and absurd in front of every open. Nothing breaks if it never runs — the
 * directory just grows — so it is also allowed to fail silently.
 *
 * Note what this does not need to do: hunt for entries whose media has been
 * deleted. An entry for a file that is gone can never be used, so its
 * timestamp never advances, so it is always among the first to go. Least
 * recently used already means it.
 *
 * @returns {Promise<{ kept: number, removed: number, bytes: number }>}
 */
export async function pruneCache(dir, budget = CACHE_BUDGET_BYTES) {
  let names
  try {
    names = (await fs.readdir(dir)).filter((name) => name.endsWith(SUFFIX))
  } catch {
    return { kept: 0, removed: 0, bytes: 0 }
  }

  const entries = []
  for (const name of names) {
    try {
      const stat = await fs.stat(path.join(dir, name))
      entries.push({ name, size: stat.size, used: stat.mtimeMs })
    } catch {
      // Vanished between the listing and the stat. Nothing to account for.
    }
  }

  // Most recently used first, so what survives is what was reached for last.
  entries.sort((a, b) => b.used - a.used)

  let bytes = 0
  let kept = 0
  let removed = 0
  for (const entry of entries) {
    if (bytes + entry.size <= budget) {
      bytes += entry.size
      kept += 1
      continue
    }
    if (await fs.rm(path.join(dir, entry.name), { force: true }).then(() => true, () => false)) {
      removed += 1
    }
  }

  return { kept, removed, bytes }
}
